using namespace std;
​
int main() {
    int n,k;
    scanf("%d %d", &n, &k);
    vector<int> ans(n);
    int count = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &ans[i]);
    }
    vector<int> dp(n + 1, 0);
    int tmp = 0;
    // 计算前缀和
    for (int i = 1; i <= n;i++) {
        dp[i] = dp[i-1] + ans[i-1];
    }
    if (dp[n] < k) {
        cout << 0;
        return 0;
    }
    // 左边界向左移，右边界肯定是向右移，递增的
    int right = 1;
    for (int i = 0; i <=n ;i++) {
        for (; right <= n; right++) {
            if (dp[right] - dp[i] >= k) {
                count += (n-right+1); 
                break;
            }
        }
    }
    cout << count;
    return 0;
}

