public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int[] ans = new int[n];
​
        for (int i = 0; i < n; i++) {
            ans[i] = scanner.nextInt();
        }
​
        int[] dp = new int[n + 1];
        int count = 0;
​
        // 计算前缀和
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1] + ans[i - 1];
        }
​
        // 所有元素和小于k，直接退出
        if (dp[n] < k) {
            System.out.println(0);
            return;
        }
        // 左边界向左移，右边界肯定是向右移，递增的
        int right = 1;
        // 双指针
        for (int i = 0; i <= n; i++) {
            for (; right <= n; right++) {
                // 剪枝: 数组全为正整数，当前位置后的数肯定大于当前值
                if (dp[right] - dp[i] >= k) {
                    count += (n - right + 1);
                    break;
                }
            }
        }
​
        System.out.println(count);
    }
}
