function getResult(n, x, arr) {
    const preSum = new Array(n + 1);
​
    preSum[0] = 0;
    // 计算前缀和
    for (let i = 1; i <= n; i++) {
        preSum[i] = preSum[i - 1] + arr[i - 1];
    }
​
    let l = 0;
   // 左边界向左移，右边界肯定是向右移，递增的
    let r = 1;
    let ans = 0;
​
    while (r <= n) {
         // 剪枝: 数组全为正整数，当前位置后的数肯定大于当前值
        if (preSum[r] - preSum[l] >= x) {
            ans += n - r + 1;
            l++;
        } else {
            r++;
        }
    }
​
    return ans;
}
