package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    // 使用 bufio.NewReader 来读取输入
    reader := bufio.NewReader(os.Stdin)
​
    // 读取第一行输入
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)
    nk := strings.Split(line, " ")
    n, _ := strconv.Atoi(nk[0])
    k, _ := strconv.Atoi(nk[1])
​
    // 读取第二行输入
    line, _ = reader.ReadString('\n')
    line = strings.TrimSpace(line)
    ansStr := strings.Split(line, " ")
    ans := make([]int, n)
    for i := 0; i < n; i++ {
        ans[i], _ = strconv.Atoi(ansStr[i])
    }
​
    // 初始化
    count := 0
    dp := make([]int, n+1)
​
    // 计算前缀和
    for i := 1; i <= n; i++ {
        dp[i] = dp[i-1] + ans[i-1]
    }
​
    // 如果总和小于 k，直接返回 0
    if dp[n] < k {
        fmt.Println(0)
        return
    }
​
    // 双指针
    right := 1
    for i := 0; i <= n; i++ {
        // 前缀和后面的数肯定大于前面的
        for right <= n && dp[right]-dp[i] < k {
            right++
        }

        if right <= n {
            count += (n - right + 1)
        }
    }
​
    // 输出结果
    fmt.Println(count)
}
